// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity. A
// change that raises the value is an upgrade: it applies at once and is billed at once, prorated for the time left in the
// current period. A change that lowers it is a downgrade: it is pending until the next renewal. A change that keeps the value
// applies at once and bills nothing, and so does any change to a trialing subscription. A change to a subscription with a
// pending downgrade starts from the pending plan and quantity.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	planID, qty := cur.PlanID, cur.Quantity
	if cur.PendingPlanID != nil {
		planID, qty = *cur.PendingPlanID, *cur.PendingQuantity
	}
	if in.PlanID != nil {
		planID = *in.PlanID
	}
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	if qty < 1 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	newPlan, ok := s.Store.Plan(orgID, planID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval || oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	oldValue, newValue := oldPlan.UnitAmount*int64(cur.Quantity), newPlan.UnitAmount*int64(qty)
	upgrade := cur.Status != store.Trialing && newValue > oldValue
	downgrade := cur.Status != store.Trialing && newValue < oldValue

	now := s.Clock.Now()
	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		if downgrade {
			p, q := planID, qty
			x.PendingPlanID, x.PendingQuantity = &p, &q
			return nil
		}
		x.PlanID, x.Quantity = planID, qty
		x.PendingPlanID, x.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
