	if upgrade {
		paid, err := s.prorate(ctx, cur, oldPlan, sub, newPlan, now)
		if err != nil {
			return sub, err
		}
		if !paid {
			if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
				return sub, err
			}
		}
	}
	return sub, nil
}

// prorate bills an upgrade now for the time left in the current period: it credits the unused time on the old plan and
// charges the remaining time on the new plan. It reports false when the charge was declined.
func (s *Service) prorate(ctx context.Context, cur store.Subscription, oldPlan store.Plan, sub store.Subscription, newPlan store.Plan, now time.Time) (bool, error) {
	length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	remaining := min(max(int64(sub.CurrentPeriodEnd.Sub(now)/time.Second), 0), length)
	ps, pe := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
	lines := []store.Line{
		{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldPlan.UnitAmount*int64(cur.Quantity), remaining, length)},
		{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newPlan.UnitAmount*int64(sub.Quantity), remaining, length)},
	}
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: oldPlan.Currency,
		Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, now)
	if err != nil {
		return false, err
	}
	s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	return s.charge(ctx, sub.OrgID, inv.ID)
}

