func TestUpgradeIsProratedAndBilledAtOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	// 21 of the period's 31 days are left: the unused 2000 is credited for 21/31 of it, the 5000 of Pro is charged for 21/31.
	e.Clock.Set(e.Clock.Now().AddDate(0, 0, 10))
	planID := pro.ID
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &planID})
	if err != nil {
		t.Fatal(err)
	}
	if got.PlanID != pro.ID || got.Status != store.Active || got.PendingPlanID != nil || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("upgraded = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoicePaid || len(invs[1].Lines) != 2 {
		t.Fatalf("invoices = %+v", invs)
	}
	if invs[1].Lines[0] != (store.Line{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}) ||
		invs[1].Lines[1] != (store.Line{Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 3387}) {
		t.Fatalf("upgrade lines = %+v", invs[1].Lines)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 {
		t.Fatalf("charges = %+v", cs)
	}
}

