83	// UpdateInput changes a subscription; nil fields stay as they are.
84	type UpdateInput struct {
85		PlanID   *string
86		Quantity *int
87	}
88	
89	// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity. A
90	// change that raises the value is an upgrade: it applies at once and is billed at once, prorated for the time left in the
91	// current period. A change that lowers it is a downgrade: it is pending until the next renewal. A change that keeps the value
92	// applies at once and bills nothing, and so does any change to a trialing subscription. A change to a subscription with a
93	// pending downgrade starts from the pending plan and quantity.
94	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
95		if in.PlanID != nil {
96			p, ok := s.Store.Plan(orgID, *in.PlanID)
97			if !ok {
98				return store.Subscription{}, store.ErrNotFound
99			}
100			if !p.Active {
101				return store.Subscription{}, ErrPlanInactive
102			}
103		}
104		cur, ok := s.Store.Subscription(orgID, id)
105		if !ok {
106			return store.Subscription{}, store.ErrNotFound
107		}
108		if cur.Status == store.Canceled {
109			return store.Subscription{}, ErrCanceled
110		}
111		oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
112		if !ok {
113			return store.Subscription{}, store.ErrNotFound
114		}
115		planID, qty := cur.PlanID, cur.Quantity
116		if cur.PendingPlanID != nil {
117			planID, qty = *cur.PendingPlanID, *cur.PendingQuantity
118		}
119		if in.PlanID != nil {
120			planID = *in.PlanID
121		}
122		if in.Quantity != nil {
123			qty = *in.Quantity
124		}
125		if qty < 1 {
126			return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
127		}
128		newPlan, ok := s.Store.Plan(orgID, planID)
129		if !ok {
130			return store.Subscription{}, store.ErrNotFound
131		}
132		if oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval || oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered {
133			return store.Subscription{}, ErrIncompatiblePlan
134		}
135		oldValue, newValue := oldPlan.UnitAmount*int64(cur.Quantity), newPlan.UnitAmount*int64(qty)
136		upgrade := cur.Status != store.Trialing && newValue > oldValue
137		downgrade := cur.Status != store.Trialing && newValue < oldValue
138	
139		now := s.Clock.Now()
140		sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
141			if x.Status == store.Canceled {
142				return ErrCanceled
143			}
144			if downgrade {
145				p, q := planID, qty
146				x.PendingPlanID, x.PendingQuantity = &p, &q
147				return nil
148			}
149			x.PlanID, x.Quantity = planID, qty
150			x.PendingPlanID, x.PendingQuantity = nil, nil
151			return nil
152		})
153		if err != nil {
154			return store.Subscription{}, err
155		}
156		s.publish(ctx, orgID, "subscription.updated", sub)
157		if upgrade {
158			paid, err := s.prorate(ctx, cur, oldPlan, sub, newPlan, now)
159			if err != nil {
160				return sub, err
161			}
162			if !paid {
163				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
164					return sub, err
165				}
166			}
167		}
168		return sub, nil
169	}
