171	// prorate bills an upgrade now for the time left in the current period: it credits the unused time on the old plan and
172	// charges the remaining time on the new plan. It reports false when the charge was declined.
173	func (s *Service) prorate(ctx context.Context, cur store.Subscription, oldPlan store.Plan, sub store.Subscription, newPlan store.Plan, now time.Time) (bool, error) {
174		length := int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
175		remaining := min(max(int64(sub.CurrentPeriodEnd.Sub(now)/time.Second), 0), length)
176		ps, pe := sub.CurrentPeriodStart, sub.CurrentPeriodEnd
177		lines := []store.Line{
178			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldPlan.UnitAmount*int64(cur.Quantity), remaining, length)},
179			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newPlan.UnitAmount*int64(sub.Quantity), remaining, length)},
180		}
181		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: oldPlan.Currency,
182			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, now)
183		if err != nil {
184			return false, err
185		}
186		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
187		return s.charge(ctx, sub.OrgID, inv.ID)
188	}
189	
190	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
191	// subscription changes nothing.
192	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
193		now := s.Clock.Now()
194		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
195			if sub.Status == store.Canceled {
196				return nil
197			}
198			if atPeriodEnd {
199				sub.CancelAtPeriodEnd = true
200				return nil
201			}
202			sub.Status, sub.CanceledAt = store.Canceled, &now
203			return nil
204		})
205		if err != nil {
206			return store.Subscription{}, err
207		}
208		if sub.Status == store.Canceled {
209			s.publish(ctx, orgID, "subscription.canceled", sub)
210		} else {
211			s.publish(ctx, orgID, "subscription.updated", sub)
212		}
213		return sub, nil
214	}
215	
216	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
217	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
218	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
219	// due. RenewDue returns how many subscriptions it renewed or canceled.
220	func (s *Service) RenewDue(ctx context.Context) (int, error) {
221		now := s.Clock.Now()
222		n := 0
223		for _, sub := range s.Store.DueSubscriptions(now) {
224			if err := ctx.Err(); err != nil {
225				return n, err
226			}
227			if err := s.renew(ctx, sub, now); err != nil {
228				return n, fmt.Errorf("renew %s: %w", sub.ID, err)
229			}
230			n++
231		}
232		return n, nil
233	}
234	
235	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
236		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
237		if !ok {
238			return store.ErrNotFound
239		}
240		if sub.CancelAtPeriodEnd {
241			end := sub.CurrentPeriodEnd
242			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
243				x.Status, x.CanceledAt = store.Canceled, &end
244				return nil
245			})
246			if err == nil {
247				s.publish(ctx, sub.OrgID, "subscription.canceled", sub)
248			}
249			return err
250		}
251		// A pending downgrade takes effect at this renewal, which bills the new plan and quantity.
252		next := sub
253		if sub.PendingPlanID != nil {
254			if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
255				return store.ErrNotFound
256			}
257			next.PlanID, next.Quantity = plan.ID, *sub.PendingQuantity
258		}
259		start := now
260		end := billing.AddInterval(start, plan.Interval)
261		paid := true
262		var err error
263		switch {
264		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
265			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
266		case plan.UsageType == store.Licensed:
267			paid, err = s.invoicePeriod(ctx, next, plan, start, end)
268		}
269		if err != nil {
270			return err
271		}
272		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
273			x.PlanID, x.Quantity = next.PlanID, next.Quantity
274			x.PendingPlanID, x.PendingQuantity = nil, nil
275			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
276			if paid {
277				x.Status = store.Active
278			} else {
279				x.Status = store.PastDue
280			}
281			return nil
282		})
283		if err != nil {
284			return err
285		}
286		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
287		return nil
288	}
289	
290	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
291	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
292	// payment method stays open and counts as paid here (it is paid by hand).
293	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
294		var lines []store.Line
295		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
296		switch plan.UsageType {
297		case store.Licensed:
298			if plan.UnitAmount > 0 {
299				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
300			}
301		case store.Metered:
302			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
303				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
304			}
305		}
306		ps, pe := start, end
307		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
308			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
309		if err != nil {
310			return false, err
311		}
312		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
313		return s.charge(ctx, sub.OrgID, inv.ID)
314	}
315	
316	// charge charges an invoice to the customer's default payment method. It reports false when the charge was declined.
317	func (s *Service) charge(ctx context.Context, orgID, invID string) (bool, error) {
318		_, _, err := s.Payments.Pay(ctx, orgID, invID, "")
319		var decline *payments.DeclineError
320		switch {
321		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
322			return true, nil
323		case errors.As(err, &decline):
324			return false, nil
325		default:
326			return false, err
327		}
328	}
329	
330	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
331		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
332			x.Status = st
333			return nil
334		})
335		if err == nil {
336			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
337		}
338		return sub, err
339	}
340	
341	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
342		if s.Publisher != nil {
343			_ = s.Publisher.Publish(ctx, orgID, typ, data)
344		}
345	}
