41	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
42	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
43	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
44	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
45		plan, ok := s.Store.Plan(orgID, in.PlanID)
46		if !ok {
47			return store.Subscription{}, store.ErrNotFound
48		}
49		if !plan.Active {
50			return store.Subscription{}, ErrPlanInactive
51		}
52		if in.Quantity == 0 {
53			in.Quantity = 1
54		}
55		now := s.Clock.Now()
56		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
57			StartedAt: now, CurrentPeriodStart: now}
58		if plan.TrialDays > 0 {
59			end := now.AddDate(0, 0, plan.TrialDays)
60			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
61		} else {
62			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
63		}
64		sub, err := s.Store.CreateSubscription(sub, now)
65		if err != nil {
66			return store.Subscription{}, err
67		}
68		s.publish(ctx, orgID, "subscription.created", sub)
69		if sub.Status == store.Active && plan.UsageType == store.Licensed {
70			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
71			if err != nil {
72				return sub, err
73			}
74			if !paid {
75				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
76					return sub, err
77				}
78			}
79		}
80		return sub, nil
81	}
