235	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) error {
236		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
237		if !ok {
238			return store.ErrNotFound
239		}
240		if sub.CancelAtPeriodEnd {
241			end := sub.CurrentPeriodEnd
242			sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
243				x.Status, x.CanceledAt = store.Canceled, &end
244				return nil
