248			}
249			return err
250		}
251		// A pending downgrade takes effect at this renewal, which bills the new plan and quantity.
252		next := sub
253		if sub.PendingPlanID != nil {
254			if plan, ok = s.Store.Plan(sub.OrgID, *sub.PendingPlanID); !ok {
255				return store.ErrNotFound
256			}
257			next.PlanID, next.Quantity = plan.ID, *sub.PendingQuantity
258		}
259		start := now
260		end := billing.AddInterval(start, plan.Interval)
261		paid := true
