263		switch {
264		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
265			paid, err = s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
266		case plan.UsageType == store.Licensed:
267			paid, err = s.invoicePeriod(ctx, next, plan, start, end)
268		}
269		if err != nil {
270			return err
271		}
272		sub, err = s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
273			x.PlanID, x.Quantity = next.PlanID, next.Quantity
274			x.PendingPlanID, x.PendingQuantity = nil, nil
275			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
276			if paid {
277				x.Status = store.Active
278			} else {
279				x.Status = store.PastDue
280			}
281			return nil
282		})
283		if err != nil {
284			return err
285		}
286		s.publish(ctx, sub.OrgID, "subscription.updated", sub)
287		return nil
288	}
289	
290	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
291	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
292	// payment method stays open and counts as paid here (it is paid by hand).
293	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
294		var lines []store.Line
295		period := start.Format("Jan 2, 2006") + " to " + end.Format("Jan 2, 2006")
296		switch plan.UsageType {
297		case store.Licensed:
298			if plan.UnitAmount > 0 {
299				lines = append(lines, store.Line{Description: plan.Name + ", " + period, Quantity: int64(sub.Quantity), UnitAmount: plan.UnitAmount})
300			}
301		case store.Metered:
302			if used := s.Store.UsageTotal(sub.OrgID, sub.ID, start, end); used > 0 {
303				lines = append(lines, store.Line{Description: plan.Name + " usage, " + period, Quantity: used, UnitAmount: plan.UnitAmount})
304			}
305		}
306		ps, pe := start, end
307		inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: sub.OrgID, CustomerID: sub.CustomerID, SubscriptionID: sub.ID, Currency: plan.Currency,
308			Lines: lines, DiscountPercent: sub.DiscountPercent, PeriodStart: &ps, PeriodEnd: &pe}, s.Clock.Now())
309		if err != nil {
310			return false, err
311		}
312		s.publish(ctx, sub.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
313		return s.charge(ctx, sub.OrgID, inv.ID)
314	}
315	
316	// charge charges an invoice to the customer's default payment method. It reports false when the charge was declined.
317	func (s *Service) charge(ctx context.Context, orgID, invID string) (bool, error) {
318		_, _, err := s.Payments.Pay(ctx, orgID, invID, "")
319		var decline *payments.DeclineError
320		switch {
321		case err == nil, errors.Is(err, payments.ErrNoPaymentMethod):
322			return true, nil
323		case errors.As(err, &decline):
324			return false, nil
325		default:
326			return false, err
327		}
328	}
329	
330	func (s *Service) setStatus(ctx context.Context, sub store.Subscription, st store.SubStatus) (store.Subscription, error) {
331		sub, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
332			x.Status = st
333			return nil
334		})
335		if err == nil {
336			s.publish(ctx, sub.OrgID, "subscription.updated", sub)
337		}
338		return sub, err
339	}
340	
341	func (s *Service) publish(ctx context.Context, orgID, typ string, data any) {
342		if s.Publisher != nil {
343			_ = s.Publisher.Publish(ctx, orgID, typ, data)
344		}
345	}
