// upgrade applies an upgrade and bills it at once. Its prorated invoice is created before the change is committed, so the
// change never applies without its invoice. If the charge fails for a reason other than a decline, the change is undone and
// the invoice voided, so the caller can retry; nothing was charged. A declined charge keeps the upgrade and makes the
// subscription past due.
func (s *Service) upgrade(ctx context.Context, cur store.Subscription, oldPlan, newPlan store.Plan, planID string, qty int, now time.Time) (store.Subscription, error) {
	inv, err := s.prorate(cur, oldPlan, newPlan, qty, now)
	if err != nil {
		return store.Subscription{}, err
	}
	sub, err := s.Store.UpdateSubscription(cur.OrgID, cur.ID, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		x.PlanID, x.Quantity = planID, qty
		x.PendingPlanID, x.PendingQuantity = nil, nil
		return nil
	})
	if err != nil {
		if verr := s.void(cur.OrgID, inv.ID); verr != nil {
			err = errors.Join(err, verr)
		}
		return store.Subscription{}, err
	}
	s.publish(ctx, cur.OrgID, "subscription.updated", sub)
	s.publish(ctx, cur.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": sub.ID})
	paid, err := s.charge(ctx, cur.OrgID, inv.ID)
	if err != nil {
		if uerr := s.undo(ctx, cur, planID, qty, inv.ID); uerr != nil {
			err = errors.Join(err, uerr)
		}
		return store.Subscription{}, err
	}
	if !paid {
		if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
			return sub, err
		}
	}
	return sub, nil
}

// undo puts a subscription back the way it was before an upgrade to planID and qty that could not be charged, and voids the
// upgrade's invoice. If the subscription has changed since, its plan is left alone and only the invoice is voided.
func (s *Service) undo(ctx context.Context, cur store.Subscription, planID string, qty int, invID string) error {
	sub, err := s.Store.UpdateSubscription(cur.OrgID, cur.ID, func(x *store.Subscription) error {
		if x.PlanID != planID || x.Quantity != qty {
			return nil
		}
		x.PlanID, x.Quantity = cur.PlanID, cur.Quantity
		x.PendingPlanID, x.PendingQuantity = cur.PendingPlanID, cur.PendingQuantity
		return nil
	})
	if err != nil {
		return err
	}
	s.publish(ctx, cur.OrgID, "subscription.updated", sub)
	return s.void(cur.OrgID, invID)
}

