func TestUpgradeChargeFailureIsUndone(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_gateway_down"; return nil })
	planID := pro.ID
	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &planID}); !errors.Is(err, payments.ErrUnavailable) {
		t.Fatalf("err = %v", err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID || got.Status != store.Active || got.PendingPlanID != nil {
		t.Fatalf("subscription after the failed charge = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceVoid || len(e.Gateway.Charges()) != 0 {
		t.Fatalf("invoices after the failed charge = %+v", invs)
	}
	// Retried with a working payment method, the upgrade applies and is billed: no time has passed, so the full period is prorated.
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &planID})
	if err != nil || got.PlanID != pro.ID {
		t.Fatalf("retried upgrade = %+v, %v", got, err)
	}
	invs = e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 3 || invs[2].Status != store.InvoicePaid || len(invs[2].Lines) != 2 {
		t.Fatalf("invoices after the retry = %+v", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 1 || cs[0].Amount != 3000 {
		t.Fatalf("charges = %+v", cs)
	}
}

